// Layout: nodes by variable, comment boxes with a colour normalised to four numbers.
/// @name M_LpLayout
export void M_LpLayout(inout material Base)
{
    float Value = 0;
    float Sum = 1.0 + 2.0;
    Value = Sum;
    Base.Opacity = Value;
}

#pragma layout(Node, Var = "Sum", X = -320, Y = 48)
#pragma layout(Comment, Name = "Maths", X = -400, Y = 0, W = 300, H = 200, Color = "0.15 0.15 0.15 0.5")
